import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for batched matrix multiplication
batched_matmul_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void batched_matmul_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * m * n) {
        int batch_idx = idx / (m * n);
        int rem = idx % (m * n);
        int i = rem / n;
        int j = rem % n;
        float sum = 0.0f;
        for (int l = 0; l < k; ++l) {
            int a_idx = batch_idx * m * k + i * k + l;
            int b_idx = batch_idx * k * n + l * n + j;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}
"""

# C++ source: function declaration
batched_matmul_cpp_source = (
    "torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# CUDA source: kernel plus function body
batched_matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void batched_matmul_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * m * n) {
        int batch_idx = idx / (m * n);
        int rem = idx % (m * n);
        int i = rem / n;
        int j = rem % n;
        float sum = 0.0f;
        for (int l = 0; l < k; ++l) {
            int a_idx = batch_idx * m * k + i * k + l;
            int b_idx = batch_idx * k * n + l * n + j;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}

torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    auto C = torch::zeros((batch_size, m, n), device=A.device, dtype=A.dtype);

    const int block_size = 256;
    const int num_blocks = (batch_size * m * n + block_size - 1) / block_size;

    batched_matmul_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch_size, m, k, n
    );

    return C;
}
"""

# Load the inline function
batched_matmul = load_inline(
    name="batched_matmul",
    cpp_sources=batched_matmul_cpp_source,
    cuda_sources=batched_matmul_cuda_source,
    functions=["batched_matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.batched_matmul = batched_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs batched matrix multiplication C = A @ B.

        Args:
            A: Input tensor of shape (batch_size, m, k).
            B: Input tensor of shape (batch_size, k, n).

        Returns:
            C: Output tensor of shape (batch_size, m, n).
        """
        return self.batched_matmul(A, B)

def get_inputs():
    batch_size = 128
    m = 128 * 4
    k = 256 * 4
    n = 512 * 4
    A = torch.rand(batch_size, m, k).cuda()
    B = torch.rand(batch_size, k, n).cuda()
    return [A, B]
